# merges everyone's replaced tweets by cutting each person's row range
# and pasting it into the final file

import pandas as pd

ORIGINAL_PATH = "bot_detection_data.csv"
OUTPUT_PATH = "bot_detection_data_final.csv"

# fill in each person's file and their row range (start inclusive, end exclusive)
# e.g. rows 0 to 12500 means the first 12,500 rows
TEAMMATE_SECTIONS = [
    {"name": "kavin",    "file": "bot_detection_data_kavin_share.csv", "start": 37500, "end": 50000},
    {"name": "maggie",   "file": "maggie-second-12500",                "start": 12500, "end": 25000},
    {"name": "vanshika", "file": "vanshika_share.csv",                 "start": 0,     "end": 12500},
    {"name": "liam",     "file": "liam_share.csv",                     "start": 25000, "end": 37500},
]

# *** STILL WAITING FOR EVERYONES CSV FILE ***

final = pd.read_csv(ORIGINAL_PATH)

for section in TEAMMATE_SECTIONS:
    teammate_df = pd.read_csv(section["file"])
    start, end = section["start"], section["end"]

    # grab just this person's replaced Tweet column for their range
    final.loc[start:end-1, "Tweet"] = teammate_df.loc[start:end-1, "Tweet"].values

    print(f"{section['name']}: pasted rows {start} to {end-1}")

final.to_csv(OUTPUT_PATH, index=False)
print(f"\nSaved merged file to {OUTPUT_PATH}")